var HTML = "<meta charset=\"utf-8\">\n<!-- ============================================================\n  【B3 · 故事设定】标准组件模板 —— 实现唯一源（UI 规范「B3」的落地实现）\n  使用方式：只替换下方「数据区」（DATA 对象）→ 输出完整代码给 show_widget\n  ❌ 组件代码区一字不改（改交互 = 修改本文件一处，全库生效）\n  🚫 禁止自绘／简化／合并控件：🔒锁定 ／ 自定义 ／ 信息框 ／ 页签 ／ 开关 ／ 按钮 缺任一＝违规 → 重读本文件重渲\n  两种项目形态：pool＝□池＋信息框 ／ swaprow＝多行换选值（prefix 支持 `**` 亮色标记·不加粗） ／ poolrows＝多子组池 ／ tabpool＝横列切换池组（点选下展·哪一套就展示哪一套）\n  故事本（swaprow · mainline · 六段同构）：每段＝`段位｜作用层 钩子 情绪` 常显；🔴 **段右侧**另挂两项（side 槽 · 不进正文）\n    ＝ **取景**〔8 大类 · 单列换选 · 数据区 `candidates`＝`SCE_POOL` · 末项自定义〕＋ **内外**〔分段点选 室内／室外／户外 · 不弹层 · 数据区 `cyc`〕\n    折叠内容（按 `grp` 分组渲染 · 同组同一行；**`×` 只在 戏核行 与 时代背景行**，事件行不加 `×`）：\n      ① `事件 行动 叙事手法` ＋ `伏线`（`right:1` 无组 → 恒浮折叠首行行右）\n      ② `主线（池） × 反差（池）` ＋ `戏路`（`right:1` 有组 → 浮本组行右）＝戏核行（`emit` 回传 `戏核·主线／戏核·反差／戏核·戏路`）\n      **`事件`**＝**两个并列单值槽**：`事件`（状态/行为池 · 5 组 30 项）＋ 无名第二槽（行动池 · 5 组 30 项 · `same:1` 回传并进 `事件=`）；各点各换、**不设 `＋／－`**（`事件 困 剥桔子`）\n      **`同上`**：承／收／放／转／合 五段**除 `内外`（三态点选、不弹层）外全部换选槽**——`作用层`／`钩子`／`情绪`／`事件`／`行动`／`叙事手法`／`主线`／`反差`／`戏路`／`伏线`／`取景` 共 11 个，弹层顶部固定一行 `同上`（金 · `sameOK()` 判 `m[2-6][(ac|a|s|L|D|c|b|n|h|f|R)]` · 起段不出）→ 值＝`同上`；多值槽 `钩子`／`伏线` 选它即 `S.pools=['同上']` 清空其余、不再出 `＋`；**`行动` 选同上 ⇒ `事件` 一并同上**（联动：两槽合并、行上只显示一个 `事件 同上`，回传 `事件=同上`）；`事件=同上` 时动作槽不渲染；若之后把 `事件` 改回具体值，行动槽重新出现并仍显示 `同上`（回传 `事件=狼狈／同上`）\n      **`伏线`（两级换选 · 可 `无`）**：池 6 类 43 项（身份向/关系向/物证向/世界向/情感向/时空向）＋`无`；单列 6 推荐（末位恒 `无`）→ `更多...` → 两栏；`无` ＝独占值（`mselTake` 清空其余 · 不出 `＋` · 回传 `伏线=无`，两栏六类不含它）\n      **`戏路`**：两级换选（单列 rec 6 → 更多 → 两栏 6 类 × 6＝36 项）\n    回传：`故事本（承）：作用层=… ｜ 钩子=… ｜ 情绪=… ｜ 事件=困／剥桔子 ｜ 叙事手法=… ｜ 戏核·主线=… ｜ 戏核·反差=… ｜ 戏核·戏路=… ｜ 伏线=… ｜ 内外=室内 ｜ 取景=住宅区`\n============================================================   📌 本文件内的选项／候选池仅为示例：每期必须按本期材料重写 DATA 区，禁止直接沿用。\n  📌 身份／性格／音色／语感 四组选项：每期必须按上游材料（话题＋项目设计卡＋故事线）推理生成，文件内仅为示例，禁止沿用。\n-->\n<div class=\"ljP\">\n\n<h2 class=\"ljSr\">故事设定面板：两分区（角色设定 ／ 故事线）换选与勾选</h2>\n<div class=\"ljHd\">\n<div class=\"ljTt\">故事设定</div>\n<div class=\"ljHc\">\n<button class=\"ljHb\" onclick=\"LJ.up()\" title=\"回项目设计（B2）\"><svg viewBox=\"0 0 24 24\" width=\"13\" height=\"13\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 19V6\"/><path d=\"M6 11l6-6 6 6\"/></svg>上一级</button>\n<button class=\"ljHb\" onclick=\"LJ.skip()\" title=\"AI 按优选完成全部选择 · 直接推进剧本定稿端\">跳过<svg viewBox=\"0 0 24 24\" width=\"13\" height=\"13\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 5l7 7-7 7\"/><path d=\"M13 5l7 7-7 7\"/></svg></button>\n</div>\n</div>\n<div class=\"ljBd\"></div>\n<div class=\"ljFt\">\n<button class=\"ljBtn\" onclick=\"LJ.reset()\" title=\"还原初始呈现（AI 预选态）\"><svg viewBox=\"0 0 24 24\" width=\"13\" height=\"13\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12a8 8 0 1 0 2.34-5.66\"/><path d=\"M4 5v4h4\"/></svg>复位</button>\n<button class=\"ljBtn ljPri\" id=\"b3main\" onclick=\"LJ.confirm()\" title=\"采纳当前产出 · 定稿并推进\"><svg viewBox=\"0 0 24 24\" width=\"13\" height=\"13\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 12.5l4.5 4.5L19 7\"/></svg><span id=\"b3mainT\">确认</span></button>\n</div>\n<div class=\"ljOvl\"><div class=\"ljMod\"><div class=\"ljMoH\">回传预览 · 确认后提交 AI</div><div class=\"ljMoB\"></div><div class=\"ljMoF\"><button class=\"ljBtn\" onclick=\"LJ.closeM()\" title=\"收起（返回面板继续调整）\">收起</button><button class=\"ljBtn ljPri\" onclick=\"LJ.submit()\" title=\"将回传内容提交给 AI\"><svg viewBox=\"0 0 24 24\" width=\"13\" height=\"13\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 12.5l4.5 4.5L19 7\"/></svg>提交</button></div></div></div>\n<div class=\"ljTst\"></div>\n\n</div>\n\n<!--HA_PREVIEW-->\n<script data-panel=\"B3_故事设定\">\n/* 通用回传预览（与 B5 同款）：字数 ／ 复制全文 ／ 存 .md —— 由 tools/inject_preview.py 注入 */\n(function(){\n var PANEL=(document.currentScript&&document.currentScript.getAttribute('data-panel'))||'面板';\n function ovl(){return document.querySelector('.ljOvl.on');}\n function linesOf(mod){return [].slice.call(mod.querySelectorAll('.ljOl')).map(function(e){\n   return (e.innerText||'').replace(/\\u00a0/g,' ').trim();}).filter(function(x){return x!=='';});}\n function headOf(mod){var h=mod.querySelector('.ljMoH');var t=h?(h.innerText||'').trim():'';return t||('【'+PANEL+'·回传】');}\n function copyTxt(t){\n  function fb(){var ta=document.createElement('textarea');ta.value=t;ta.style.cssText='position:fixed;left:-9999px;top:0';document.body.appendChild(ta);ta.select();var ok=false;try{ok=document.execCommand('copy');}catch(e){}document.body.removeChild(ta);return ok;}\n  try{if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(t).then(function(){tip('已复制全文 '+t.length+' 字');},function(){tip(fb()?('已复制全文 '+t.length+' 字'):'复制被拦');});return;}}catch(e){}\n  tip(fb()?('已复制全文 '+t.length+' 字'):'复制被拦');\n }\n function saveMd(t){try{var b=new Blob([t],{type:'text/markdown;charset=utf-8'});var a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=PANEL+'_回传.md';document.body.appendChild(a);a.click();setTimeout(function(){URL.revokeObjectURL(a.href);a.remove();},800);tip('已存 '+PANEL+'_回传.md');}catch(e){copyTxt(t);}}\n function tip(s){var d=document.createElement('div');d.textContent=s;d.style.cssText='position:fixed;left:50%;bottom:64px;transform:translateX(-50%);background:rgba(23,28,34,.96);border:1px solid rgba(62,198,216,.4);color:#C9D4DE;font:12px/1.6 -apple-system,PingFang SC,sans-serif;padding:6px 16px;border-radius:8px;z-index:9999';document.body.appendChild(d);setTimeout(function(){d.remove();},1800);}\n function mkBtn(label,fn){var b=document.createElement('button');b.type='button';b.textContent=label;\n  b.style.cssText='background:transparent;border:1px solid rgba(255,255,255,.18);color:#C9D4DE;font:12px/1 -apple-system,PingFang SC,sans-serif;padding:5px 10px;border-radius:6px;cursor:pointer';\n  b.onmouseenter=function(){b.style.borderColor='rgba(62,198,216,.55)';b.style.color='#3EC6D8';};\n  b.onmouseleave=function(){b.style.borderColor='rgba(255,255,255,.18)';b.style.color='#C9D4DE';};\n  b.onclick=fn;return b;}\n function enhance(){\n  var o=ovl();if(!o)return;\n  var mod=o.querySelector('.ljMod')||o;\n  var box=mod.querySelector('.ljMoB');if(!box)return;\n  var lines=linesOf(mod);if(!lines.length)return;\n  var txt=headOf(mod)+'\\n'+lines.join('\\n');\n  var sig=lines.length+':'+txt.length;\n  var bar=mod.querySelector('.haPv');\n  if(!bar){bar=document.createElement('div');bar.className='haPv';\n   bar.style.cssText='display:flex;align-items:center;gap:8px;margin-top:8px;padding-top:8px;border-top:1px solid rgba(255,255,255,.08);font:12px/1.6 -apple-system,PingFang SC,sans-serif;color:#8A97A3';\n   var f=mod.querySelector('.ljMoF');\n   if(f)mod.insertBefore(bar,f);else mod.appendChild(bar);}\n  if(bar.getAttribute('data-sig')===sig)return;\n  bar.setAttribute('data-sig',sig);bar.innerHTML='';\n  var info=document.createElement('span');info.textContent='共 '+lines.length+' 行 · '+txt.length+' 字';\n  var sp=document.createElement('span');sp.style.flex='1';\n  bar.appendChild(info);bar.appendChild(sp);\n  bar.appendChild(mkBtn('复制全文',function(){copyTxt(txt);}));\n  bar.appendChild(mkBtn('存 .md',function(){saveMd(txt);}));\n }\n var mo=new MutationObserver(function(){setTimeout(enhance,0);});\n try{mo.observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:['class']});}catch(e){}\n try{mo.observe(document.documentElement,{subtree:true,childList:true});}catch(e){}\n setTimeout(enhance,300);setTimeout(enhance,1200);\n})();\n\n/* ---------- 指针提交（2026-11-15 · 与 B5 同源） ----------\n   面板把分条消息交给 window.__ljSend（由本块提供），本块在 40ms 内把同一批分条收拢成全文，\n   写剪贴板 + 存 <面板>_回传.txt，只发一行指针【面板·动作】#hash · N字。\n   ⚠️ 不再改写 window.sendPrompt —— 宿主可能在面板加载后才注入，改写会扑空；\n      改为面板显式调用 __ljSend，它在每次调用时才解析当前 sendPrompt。\n   ⚠️ 本段无反斜杠转义（regex 用 indexOf/charCode 手写）。 */\n(function(){\n var P='面板';\n var el=document.querySelector('script[data-panel]');\n if(el&&el.getAttribute('data-panel'))P=el.getAttribute('data-panel');\n var NL=String.fromCharCode(10),TAB=String.fromCharCode(9);\n var buf=[],act='确认',timer=null;\n function isNum(c){var n=c.charCodeAt(0);return n>=48&&n<=57;}\n function ltrim(s){var i=0;while(i<s.length&&(s.charAt(i)===' '||s.charAt(i)===TAB))i++;return s.slice(i);}\n function parse(msg){\n  var i=msg.indexOf(NL);if(i<0)return null;\n  var h=msg.slice(0,i),b=msg.slice(i+1);\n  if(h.charAt(0)!=='【')return null;\n  var e=h.indexOf('】');if(e<0)return null;\n  var a=h.slice(1,e),tail=ltrim(h.slice(e+1));\n  var d=a.lastIndexOf('·');if(d>=0)a=a.slice(d+1);\n  var n=tail.length,j=n;\n  while(j>0&&isNum(tail.charAt(j-1)))j--;\n  var chunk=false;\n  if(j<n&&j>0&&tail.charAt(j-1)==='/'){\n   var k=j-1;while(k>0&&isNum(tail.charAt(k-1)))k--;\n   if(k<j-1)chunk=true;\n  }\n  return {act:a,body:b,chunk:chunk,len:msg.length};\n }\n function fp(t){var h=2166136261;for(var i=0;i<t.length;i++){h=Math.imul(h^t.charCodeAt(i),16777619)>>>0;}return ('0000000'+h.toString(16)).slice(-8);}\n function copy(t){\n  var ok=false,ta=document.createElement('textarea');\n  try{ta.value=t;ta.setAttribute('readonly','');ta.style.cssText='position:fixed;left:-9999px;top:0';document.body.appendChild(ta);ta.select();ta.setSelectionRange(0,t.length);ok=document.execCommand('copy');}catch(e){ok=false;}\n  if(ta.parentNode)ta.parentNode.removeChild(ta);\n  if(!ok){try{if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(t);ok=true;}}catch(e){}}\n  return ok;\n }\n function save(t){try{var b=new Blob([t],{type:'text/plain;charset=utf-8'}),a=document.createElement('a');\n  a.href=URL.createObjectURL(b);a.download=P+'_回传.txt';document.body.appendChild(a);a.click();document.body.removeChild(a);\n  setTimeout(function(){URL.revokeObjectURL(a.href);},1500);}catch(e){}}\n function raw(){return (typeof window.sendPrompt==='function')?window.sendPrompt:null;}\n function flush(){\n  var t=buf.join(NL);buf=[];timer=null;if(!t)return;\n  var sp=raw();if(!sp)return;\n  var ok=copy(t);save(t);\n  if(ok)sp('【'+P+'·'+act+'】#'+fp(t)+' · '+t.length+'字 · 见剪贴板／'+P+'_回传.txt');\n  else sp(t);\n }\n window.__ljSend=function(msg){\n  if(typeof msg!=='string'){var s0=raw();return s0?s0.apply(window,arguments):false;}\n  var p=parse(msg);\n  if(p&&(p.chunk||p.len>450)){act=p.act;buf.push(p.body);if(timer)clearTimeout(timer);timer=setTimeout(flush,40);return true;}\n  var sp=raw();return sp?sp(msg):false;\n };\n})();\n</script>\n\n<!--/HA_PREVIEW-->";
