/* 角色槽注册：身份 ／ 定位 ／ 语境 ＝ 值槽（单列推荐 → 更多 → 两栏 · 带 `＋／－`）
   池＝`groups`（组 × 项）；`options` 由 groups 派生（兜底用），值存 S.pools（可多值） */
function regSlotG(g){
  if(!g||!g.slot)return;
  if(!g.options||!g.options.length){
    var o=[];(g.groups||[]).forEach(function(kv){(kv[1]||[]).forEach(function(v){if(o.indexOf(v)<0)o.push(v);});});g.options=o;
  }
  SLOTS[g.key]={key:g.key,label:g.label,multi:1,max:MAXK[g.key]||g.max||3,
    candidates:g.options.slice(),rec:(g.rec||[]).slice(),groups:(g.groups||[]).slice()};
}
DATA.sections.forEach(function(sec){sec.items.forEach(function(it){
  if(it.type!=='rtabs')return;
  it.tabs.forEach(function(t){(t.groups||[]).forEach(regSlotG);});
});});
/* 六段值槽注册：钩子／伏线 ＝ 多值槽（多值 → S.pools 数组 · 上限 2）
   同一个 `＋／－` 口径与弹层（单列推荐 → 更多 → 两栏），所以直接复用角色槽那套（rslot／rslotAdd／rslotDel） */
